<script setup>
import {ref,onMounted,onBeforeUnmount,nextTick} from 'vue'
import {captureAnimationLayers,drawAnimation,encodeAnimation,DEFAULT_EFFECTS} from '@/services/publicationAnimation'
const props=defineProps({getElement:{type:Function,required:true},name:{type:String,default:'galaxia-publicacion'}})
const emit=defineEmits(['close'])
const canvas=ref(null),dialog=ref(null),effects=ref({...DEFAULT_EFFECTS,backgroundMotion:'none',backgroundIntensity:50}),format=ref('mp4'),busy=ref(false),preparing=ref(true),playing=ref(false),time=ref(0),progress=ref(0),error=ref('')
const labels={hologram:'Reflejo holográfico en fondo',title:'Entrada animada del título',pill:'Píldora con resplandor vivo',button:'Brillo deslizante del botón',particles:'Partículas ascendentes',stars:'Pequeñas estrellas ascendentes',time:'Movimiento suave de la hora',loop:'Ciclo suave (repetición)'}
let layers,raf,controller=new AbortController(),disposed=false,previousFocus,overflow
function render(){if(layers&&canvas.value)drawAnimation(canvas.value.getContext('2d'),layers,time.value,effects.value)}
function pause(){cancelAnimationFrame(raf);playing.value=false}
function play(){pause();if(time.value>=8)time.value=0;playing.value=true;const start=performance.now()-time.value*1000;const tick=now=>{const elapsed=(now-start)/1000;time.value=effects.value.loop?elapsed%8:Math.min(8,elapsed);render();if(effects.value.loop||time.value<8)raf=requestAnimationFrame(tick);else playing.value=false};raf=requestAnimationFrame(tick)}
function scrub(){pause();render()}
async function prepare(){preparing.value=true;error.value='';try{layers=await captureAnimationLayers(props.getElement(),controller.signal);if(disposed)return;canvas.value.width=layers.width;canvas.value.height=layers.height;render();if(!matchMedia('(prefers-reduced-motion: reduce)').matches)play()}catch(e){if(e.name!=='AbortError')error.value=e.message}finally{preparing.value=false}}
async function download(){pause();busy.value=true;progress.value=0;error.value='';try{const blob=await encodeAnimation(canvas.value,layers,{format:format.value,effects:{...effects.value},signal:controller.signal,onProgress:v=>progress.value=Math.round(v*100)});if(disposed)return;const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=props.name.replace(/[^\p{L}\p{N}_-]+/gu,'-')+'-cinematica-suave.'+format.value;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000)}catch(e){if(e.name!=='AbortError')error.value=e.message}finally{busy.value=false;time.value=0;render()}}
function close(){controller.abort();emit('close')}
function keys(e){if(e.key==='Escape'){e.preventDefault();close()}if(e.key==='Tab'){const items=[...dialog.value.querySelectorAll('button,input,select,[tabindex]')].filter(n=>!n.disabled&&n.offsetParent);const first=items[0],last=items.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}}
onMounted(async()=>{previousFocus=document.activeElement;overflow=document.body.style.overflow;document.body.style.overflow='hidden';await nextTick();dialog.value.focus();prepare()})
onBeforeUnmount(()=>{disposed=true;controller.abort();pause();document.body.style.overflow=overflow;previousFocus?.focus();layers=null})
</script>
<template>
<Teleport to="body"><div class="animation-backdrop" @click.self="close"><section ref="dialog" class="publication-animation" role="dialog" aria-modal="true" aria-labelledby="animation-title" tabindex="-1" @keydown="keys">
<header><div><small>GALAXIA · VÍDEO</small><h2 id="animation-title">Animar publicación</h2><p>Cinemática suave · 8 segundos · 30 fps · Sin audio</p></div><button aria-label="Cerrar animación" @click="close">✕</button></header>
<div class="animation-layout"><div class="animation-screen"><canvas ref="canvas" aria-label="Previsualización de la publicación animada"></canvas><p v-if="preparing" role="status">Preparando las capas…</p></div><div class="animation-settings">
<p>Se anima la diapositiva seleccionada. El ciclo suave prepara el final para enlazar con el inicio; activa la repetición al reproducir el vídeo. Tus capas y el diseño estático siguen editables al volver al editor.</p>
<fieldset :disabled="busy||preparing||!layers"><legend>Efectos</legend><label v-for="(label,key) in labels" :key="key"><input v-model="effects[key]" type="checkbox" @change="render"/>{{ label }}</label>
<template v-if="layers?.background"><label>Movimiento del fondo<select v-model="effects.backgroundMotion" @change="render"><option value="none">Sin movimiento</option><option value="zoom">Zoom suave</option><option value="pan">Desplazamiento lateral</option><option value="float">Flotación suave</option></select></label><label v-if="effects.backgroundMotion!=='none'">Intensidad · {{ effects.backgroundIntensity }} %<input v-model.number="effects.backgroundIntensity" aria-label="Intensidad del movimiento del fondo" type="range" min="0" max="100" step="5" @input="render"/></label><p>El movimiento se aplica a la imagen de fondo. El texto conserva su posición y el efecto se incluye en el vídeo exportado.</p></template>
<label>Exportación<select v-model="format"><option value="mp4">MP4 · H.264 para TikTok</option><option value="webm">WebM · MediaRecorder</option></select></label>
<div class="animation-playback"><button @click="playing?pause():play()">{{ playing?'Pausar':'Previsualizar' }}</button><span>{{ time.toFixed(1) }} / 8 s</span></div><input v-model.number="time" aria-label="Posición de la animación" type="range" min="0" max="8" step="0.033333" @input="scrub"/>
<button class="animation-export" @click="download">Exportar {{ format.toUpperCase() }}</button></fieldset>
<p v-if="busy" role="status">Codificando vídeo real · {{ progress }} %</p><p v-if="format==='webm'">La grabación WebM dura 8 segundos. Mantén esta pestaña visible.</p><p v-if="error" class="animation-error" role="alert">{{ error }}</p><button v-if="error&&!layers" @click="prepare">Reintentar</button><button v-if="busy" @click="close">Cancelar exportación</button>
</div></div></section></div></Teleport>
</template>
<style scoped>
.animation-backdrop{position:fixed;inset:0;z-index:6500;background:#020617df;backdrop-filter:blur(12px);display:grid;place-items:center;padding:18px}.publication-animation{width:min(100%,1060px);max-height:94dvh;overflow:auto;overscroll-behavior:contain;background:#101426;border:1px solid #a78bfa55;border-radius:22px;padding:22px;color:#f1f5f9;box-sizing:border-box}.publication-animation header{display:flex;justify-content:space-between;align-items:start;gap:14px}.publication-animation h2{font-size:25px;margin:5px 0}.publication-animation small{color:#c4b5fd;font-weight:800}.publication-animation p{font-size:13px;line-height:1.6;color:#b9c3d8}.publication-animation button,.publication-animation select{background:#26203e;border:1px solid #b59bea55;border-radius:10px;padding:11px 14px;color:#fff;cursor:pointer;font:inherit}.publication-animation button:focus-visible,.publication-animation input:focus-visible,.publication-animation select:focus-visible{outline:2px solid #67e8f9;outline-offset:3px}.animation-layout{display:grid;grid-template-columns:minmax(0,1fr) minmax(250px,.8fr);gap:24px;margin-top:16px}.animation-screen{min-width:0;background:#050816;border-radius:12px;overflow:hidden;display:grid;place-items:center}.animation-screen canvas{display:block;max-width:100%;max-height:65dvh;width:auto;height:auto}.animation-settings{min-width:0}.animation-settings fieldset{border:0;margin:0;padding:0;display:grid;gap:17px}.animation-settings legend{font-weight:800;margin-bottom:14px}.animation-settings label{display:flex;align-items:center;gap:10px;font-size:14px;flex-wrap:wrap}.animation-settings select{width:100%}.animation-settings input[type=range]{width:100%;accent-color:#a78bfa}.animation-settings input[type=checkbox]{accent-color:#a78bfa;width:18px;height:18px}.animation-playback{display:flex;align-items:center;justify-content:space-between;font-size:13px}.animation-export{background:linear-gradient(110deg,#7c3aed,#c12ca3)!important;font-weight:800!important}.animation-error{color:#fda4af!important}fieldset:disabled{opacity:.5}@media(max-width:650px){.animation-backdrop{padding:8px}.publication-animation{padding:16px;max-height:96dvh}.animation-layout{grid-template-columns:1fr;gap:14px}.animation-screen canvas{max-height:45dvh}.publication-animation h2{font-size:21px}}
</style>
